const axios = require('axios');
if (!argumentName) return sendTrackedMessage(sock, remoteJid, 'Usage: !define <word>');
await sendTrackedMessage(sock, remoteJid, '📖 Looking up word...');
try {
  const word = argumentName.trim().toLowerCase();
  const res = await axios.get(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(word)}`);
  if (!res.data || !res.data[0]) {
    return sendTrackedMessage(sock, remoteJid, `❌ No definition found for '${word}'`);
  }
  const entry = res.data[0];
  let msg = `📖 *${entry.word}*`;
  if (entry.phonetic) msg += ` ${entry.phonetic}`;
  msg += '\n\n';
  for (const meaning of entry.meanings.slice(0, 2)) {
    msg += `_${meaning.partOfSpeech}_\n`;
    for (const def of meaning.definitions.slice(0, 2)) {
      msg += `• ${def.definition}\n`;
      if (def.example) msg += `  _Example: ${def.example}_\n`;
    }
    msg += '\n';
  }
  await sendTrackedMessage(sock, remoteJid, msg);
} catch (e) {
  await sendTrackedMessage(sock, remoteJid, '❌ Word not found in dictionary.');
}
